import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import { NextResponse } from 'next/server';

import { ATTACKS_DIR } from '@/server/world';

/**
 * GET /api/attacks/report — the Step 13 attack report, served from the
 * generated artifact only (regenerated by pnpm demo:attacks / CI and baked
 * into the demo image at build time). This route NEVER runs the 60-scenario
 * suite — not on load, not via a query parameter — so a public caller cannot
 * trigger expensive server-side work. A missing artifact fails safely (503).
 */
export async function GET(): Promise<NextResponse> {
  const file = join(ATTACKS_DIR, 'attack-report.json');
  if (!existsSync(file)) {
    return NextResponse.json(
      { error: 'ATTACK_REPORT_UNAVAILABLE', detail: 'attack-report.json has not been generated (run pnpm demo:attacks)' },
      { status: 503 },
    );
  }
  try {
    return NextResponse.json(JSON.parse(readFileSync(file, 'utf8')));
  } catch (e) {
    return NextResponse.json(
      { error: 'ATTACK_REPORT_UNAVAILABLE', detail: e instanceof Error ? e.message : String(e) },
      { status: 503 },
    );
  }
}
